hooks.command:
python3 -c "import json,sys,os,re;d=json.load(sys.stdin);c=d.get('tool_input',{}).get('command','');
block=lambda m:(print('HOOK BLOCKED: '+m),sys.exit(2));
re.search(r'git\\b[^;|&]*\\bpush\\b[^;|&]*\\bmain\\b|git\\b[^;|&]*\\bmerge\\b[^;|&]*\\bmain\\b|gh\\b[^;|&]*\\bpr merge\\b',c) and block('Never push to main or merge. Open a PR instead.');
re.search(r'rm -rf /(\\s|$)|sudo rm|drop\\s+table|delete\\s+from.*where\\s+1',c,re.I) and block('Destructive command requires explicit approval.');
re.search(r'resend|sendEmail|send_email|mail\\(',c) and block('Never email users without Rune explicit approval. Ask first.');
flag=os.path.join(os.environ.get('CLAUDE_PROJECT_DIR','.'),'.git','.rig-tests-passed');
re.search(r'git commit|gh pr create',c) and not os.path.exists(flag) and block('Run the test suite first - the tests-passed marker is missing. It is written only when a test command SUCCEEDS, and it expires when code changes after the run.')"
